mapper.update:
update oa_purchase
set status = 'submitting', approval_instance_id = null,
    approval_round = #{businessRound}, last_approval_event_key = null,
    update_by = #{updateBy}, update_time = sysdate(),
    row_version = row_version + 1
where purchase_id = #{purchaseId}
  and status = #{expectedStatus}
  and row_version = #{expectedVersion}

update oa_purchase
set status = 'pending', approval_instance_id = #{instanceId},
    update_by = #{updateBy}, update_time = sysdate(),
    row_version = row_version + 1
where purchase_id = #{purchaseId}
  and status = 'submitting'
  and approval_round = #{businessRound}
  and row_version = #{expectedVersion}
  and approval_instance_id is null

